contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _log) public payable {
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        bool reverted;
        c.SetLogFile(_log); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        assert(!reverted ? (afterMinSum == beforeMinSum && afterBalance == beforeBalance) : (afterMinSum == beforeMinSum && afterBalance == beforeBalance));
    }

    receive() external payable {}
}

